package com.taller.gestion.controller;
import com.taller.gestion.domain.*; import com.taller.gestion.repository.*; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*;
@RestController @RequestMapping("/api/dashboard") @CrossOrigin(origins="*") public class DashboardController { private final WorkOrderRepository orders; private final PartRepository parts; public DashboardController(WorkOrderRepository o,PartRepository p){orders=o;parts=p;} @GetMapping public Map<String,Object> summary(){LocalDateTime start=LocalDate.now().atStartOfDay();return Map.of("vehiclesToday",orders.countByReceivedAtBetween(start,start.plusDays(1)),"inRepair",orders.countByStatus(OrderStatus.EN_REPARACION),"ready",orders.countByStatus(OrderStatus.LISTO),"lowStock",parts.findAll().stream().filter(Part::isLowStock).toList());} }
